function findAuthor(ctx, id) {
  const [author] = ctx.db.query(ctx.sql`SELECT id, name FROM author WHERE id = ${id}`);
  if (!author) {
    ctx.reject({ message: `author ${id} does not exist`, pointer: "/author_id", hint: "Create the author first with POST /authors." });
  }
  return author;
}

function refuseUnnamedPublication(ctx, author) {
  if (!author.name) {
    ctx.reject({ message: "a book whose author has no name cannot be published", pointer: "/published", hint: "Publish only books whose author has a name." });
  }
}

export function create(input, ctx) {
  const author = findAuthor(ctx, input.author_id);
  const published = input.published === true;
  if (published) refuseUnnamedPublication(ctx, author);
  const [row] = ctx.db.query(ctx.sql`INSERT INTO book (title, author_id, published) VALUES (${input.title}, ${input.author_id}, ${published}) RETURNING id`);
  return row.id;
}

export function update(input, ctx) {
  const [book] = ctx.db.query(ctx.sql`SELECT author_id, published FROM book WHERE id = ${ctx.id}`);
  const authorId = "author_id" in input ? input.author_id : book.author_id;
  const published = "published" in input ? input.published === true : book.published;
  if (published) refuseUnnamedPublication(ctx, findAuthor(ctx, authorId));
  if ("title" in input) ctx.db.exec(ctx.sql`UPDATE book SET title = ${input.title} WHERE id = ${ctx.id}`);
  if ("author_id" in input) ctx.db.exec(ctx.sql`UPDATE book SET author_id = ${input.author_id} WHERE id = ${ctx.id}`);
  if ("published" in input) ctx.db.exec(ctx.sql`UPDATE book SET published = ${published} WHERE id = ${ctx.id}`);
}

export function remove(input, ctx) {
  ctx.db.exec(ctx.sql`DELETE FROM book WHERE id = ${ctx.id}`);
}

